import math

def largest_divisor(n: int) -> int:
    """ For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largest_divisor(15)
    5
    """
    # Validate input: for n <= 1 there is no proper divisor less than n
    if n <= 1:
        raise ValueError("n must be greater than 1 to have a proper divisor smaller than n")

    largest = 1  # 1 is always a proper divisor for n > 1
    root = math.isqrt(n)

    for i in range(1, root + 1):
        if n % i == 0:
            j = n // i
            if i < n and i > largest:
                largest = i
            if j < n and j > largest:
                largest = j

    return largest

def flip_case(string: str) -> str:
    """ For a given string, flip lowercase characters to uppercase and uppercase to lowercase.
    >>> flip_case('Hello')
    'hELLO'
    """
    result_chars = []
    for c in string:
        if c.islower():
            result_chars.append(c.upper())
        elif c.isupper():
            result_chars.append(c.lower())
        else:
            result_chars.append(c)
    return ''.join(result_chars)

def unique(l: list):
    """Return sorted unique elements in a list
    >>> unique([5, 3, 5, 2, 3, 3, 9, 0, 123])
    [0, 2, 3, 5, 9, 123]
    """
    # Fast path for hashable elements
    try:
        return sorted(set(l))
    except TypeError:
        # Handle unhashable elements by preserving first occurrences
        seen = []
        for item in l:
            if item not in seen:
                seen.append(item)
        # Try to sort the deduplicated list; if items are not comparable, return as-is
        try:
            return sorted(seen)
        except TypeError:
            return seen

def encode_shift(s: str):
    """
    returns encoded string by shifting every character by 5 in the alphabet.
    """
    return "".join([chr(((ord(ch) + 5 - ord("a")) % 26) + ord("a")) for ch in s])


def decode_shift(s: str):
    """
    takes as input string encoded with encode_shift function. Returns decoded string.
    """
    # Reverse the shift applied in encode_shift by subtracting 5 (mod 26).
    return "".join([chr(((ord(ch) - 5 - ord("a")) % 26) + ord("a")) for ch in s])

def is_happy(s):
    """You are given a string s.
    Your task is to check if the string is happy or not.
    A string is happy if its length is at least 3 and every 3 consecutive letters are distinct
    """
    if not isinstance(s, str):
        # If input is not a string, it's not considered happy by this specification.
        return False

    if len(s) < 3:
        return False

    for i in range(len(s) - 2):
        if len({s[i], s[i + 1], s[i + 2]}) != 3:
            return False

    return True

def starts_one_ends(n):
    """
    Given a positive integer n, return the count of the numbers of n-digit
    positive integers that start or end with 1.
    """
    if not isinstance(n, int) or n < 1:
        raise ValueError("n must be a positive integer")
    if n == 1:
        return 1
    return 18 * (10 ** (n - 2))

def add(lst):
    """Given a non-empty list of integers lst, add the even elements that are at odd indices.

    Examples:
        add([4, 2, 6, 7]) ==> 2 
    """
    total = 0
    for idx, val in enumerate(lst):
        if idx % 2 == 1 and val % 2 == 0:
            total += val
    return total

def sort_array(array):
    """
    Given an array of non-negative integers, return a copy of the given array after sorting,
    you will sort the given array in ascending order if the sum( first index value, last index value) is odd,
    or sort it in descending order if the sum( first index value, last index value) is even.

    Note:
    * don't change the given array.
    """
    # Return a new empty list if input is empty
    if not array:
        return []

    total = array[0] + array[-1]
    if total % 2 == 1:
        return sorted(array)
    else:
        return sorted(array, reverse=True)

def encrypt(s):
    """Create a function encrypt that takes a string as an argument and
    returns a string encrypted with the alphabet being rotated by 4 places.
    Non-letter characters are left unchanged. Case is preserved.
    """
    result_chars = []
    for c in s:
        if 'a' <= c <= 'z':
            # shift lowercase letters by 4 with wrap-around
            shifted_ord = (ord(c) - ord('a') + 4) % 26 + ord('a')
            result_chars.append(chr(shifted_ord))
        elif 'A' <= c <= 'Z':
            # shift uppercase letters by 4 with wrap-around
            shifted_ord = (ord(c) - ord('A') + 4) % 26 + ord('A')
            result_chars.append(chr(shifted_ord))
        else:
            # leave other characters unchanged
            result_chars.append(c)
    return ''.join(result_chars)

