def get_odd_collatz(n: int) -> List[int]:
    """
    Given a positive integer n, return a sorted list that has the odd numbers in Collatz sequence.

    Collatz sequence: starting at n, if current is even -> current //= 2,
    if odd -> current = 3*current + 1. Continue until reaching 1.
    Return the unique odd numbers encountered, sorted in increasing order.
    """
    if not isinstance(n, int) or n < 1:
        raise ValueError("n must be a positive integer")

    odd_values = set()
    current = n

    while True:
        if current % 2 == 1:
            odd_values.add(current)
        if current == 1:
            break
        if current % 2 == 0:
            current //= 2
        else:
            current = 3 * current + 1

    return sorted(odd_values)

def split_words(txt):
    '''
    Given a string of words, return a list of words split on whitespace, if no whitespaces exists in the text you
    should split on commas ',' if no commas exists you should return the number of lower-case letters with odd order in the
    alphabet, ord('a') = 0, ord('b') = 1, ... ord('z') = 25
    Examples
    split_words("Hello world!") ➞ ["Hello", "world!"]
    split_words("Hello,world!") ➞ ["Hello", "world!"]
    split_words("abcdef") == 3 
    '''
    # If any whitespace character exists, split on whitespace
    if any(c.isspace() for c in txt):
        return txt.split()
    # If no whitespace but commas exist, split on commas
    if ',' in txt:
        return txt.split(',')
    # Otherwise, count lowercase letters with odd zero-based alphabet index
    count = 0
    for c in txt:
        if 'a' <= c <= 'z':
            if (ord(c) - ord('a')) % 2 == 1:
                count += 1
    return count

def is_sorted(lst):
    '''
    Given a list of numbers, return whether or not they are sorted
    in ascending order. If list has more than 1 duplicate of the same
    number, return False. Assume no negative numbers and only integers.
    '''
    # Empty or single-element lists are sorted
    if len(lst) <= 1:
        return True

    # Check for any value appearing more than twice
    counts = {}
    for x in lst:
        counts[x] = counts.get(x, 0) + 1
        if counts[x] > 2:
            return False

    # Check non-decreasing order
    for i in range(len(lst) - 1):
        if lst[i] > lst[i + 1]:
            return False

    return True

def largest_smallest_integers(lst):
    '''
    Create a function that returns a tuple (a, b), where 'a' is
    the largest of negative integers, and 'b' is the smallest
    of positive integers in a list.
    If there is no negative or positive integers, return them as None.

    Examples:
    largest_smallest_integers([2, 4, 1, 3, 5, 7]) == (None, 1)
    largest_smallest_integers([]) == (None, None)
    largest_smallest_integers([0]) == (None, None)
    '''
    max_negative = None
    min_positive = None

    for x in lst:
        # Only consider numeric types; ignore non-numeric values.
        if not isinstance(x, (int, float)):
            continue
        if x < 0:
            if (max_negative is None) or (x > max_negative):
                max_negative = x
        elif x > 0:
            if (min_positive is None) or (x < min_positive):
                min_positive = x
        # zeros are ignored

    return (max_negative, min_positive)

from math import isclose

def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,
    """
    def to_float(x):
        if isinstance(x, str):
            s = x.strip().replace(',', '.')
            return float(s)
        if isinstance(x, (int, float)):
            return float(x)
        raise TypeError("Unsupported type: expected int, float, or numeric string")

    va = to_float(a)
    vb = to_float(b)

    # Treat very small differences as equality
    if isclose(va, vb, rel_tol=1e-9, abs_tol=1e-12):
        return None

    return a if va > vb else b

def is_equal_to_sum_even(n):
    """Evaluate whether the given number n can be written as the sum of exactly 4 positive even numbers
    Example
    is_equal_to_sum_even(4) == False
    is_equal_to_sum_even(6) == False
    is_equal_to_sum_even(8) == True
    """
    # Must be even and at least 2+2+2+2 = 8
    try:
        # Ensure n behaves like an integer (handles floats that are whole numbers)
        if int(n) != n:
            return False
    except Exception:
        return False

    n = int(n)
    return (n % 2 == 0) and (n >= 8)

def sum_squares(lst):
    """
    This function will take a list of integers. For all entries in the list, the function shall square the integer entry if its index is a 
    multiple of 3 and will cube the integer entry if its index is a multiple of 4 and not a multiple of 3. The function will not 
    change the entries in the list whose indexes are not a multiple of 3 or 4. The function shall then return the sum of all entries. 
    """
    total = 0
    for i, v in enumerate(lst):
        if i % 3 == 0:
            total += v ** 2
        elif i % 4 == 0:
            total += v ** 3
        else:
            total += v
    return total

