def words_in_sentence(sentence):
    """
    You are given a string representing a sentence,
    the sentence contains some words separated by a space,
    and you have to return a string that contains the words from the original sentence,
    whose lengths are prime numbers,
    the order of the words in the new string should be the same as the original one.
    """
    def is_prime(n: int) -> bool:
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0:
            return False
        limit = int(math.isqrt(n))
        for i in range(3, limit + 1, 2):
            if n % i == 0:
                return False
        return True

    words = sentence.split()
    result_words = [w for w in words if is_prime(len(w))]
    return " ".join(result_words)

import math

def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5
    """
    # Ensure n is an integer for primality checking
    try:
        n_int = int(n)
    except Exception:
        # If n cannot be interpreted as an integer, treat as non-prime
        return y

    # Standard primality checks
    if n_int < 2:
        return y
    if n_int == 2:
        return x
    if n_int % 2 == 0:
        return y

    limit = math.isqrt(n_int)
    for d in range(3, limit + 1, 2):
        if n_int % d == 0:
            return y

    return x

def even_odd_count(num):
    """Given an integer. return a tuple that has the number of even and odd digits respectively.

     Example:
        even_odd_count(-12) ==> (1, 1)
        even_odd_count(123) ==> (1, 2)
    """
    # Ensure we work with an integer and ignore sign
    n = abs(int(num))

    # Special-case zero: single digit which is even
    if n == 0:
        return (1, 0)

    evens = 0
    odds = 0

    # Count digits using arithmetic to avoid string conversion
    while n > 0:
        d = n % 10
        if d % 2 == 0:
            evens += 1
        else:
            odds += 1
        n //= 10

    return (evens, odds)
